function excelDate(num) {
  if (!num || isNaN(+num)) return null;
  const d = new Date(Date.UTC(1900, 0, 1) + (Math.floor(+num) - 2) * 86400000);
  return d.toISOString().split('T')[0];
}
function s(v) {
  if (v === null || v === undefined) return null;
  const r = String(v).trim();
  return r || null;
}
function n(v) {
  if (v === null || v === undefined || v === '') return 0;
  const r = parseFloat(String(v).replace(',', '.'));
  return isNaN(r) ? 0 : r;
}
function getMonday(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00:00Z');
  if (isNaN(d.getTime())) return null;
  const day = d.getUTCDay();
  const diff = d.getUTCDate() - day + (day === 0 ? -6 : 1);
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), diff)).toISOString().split('T')[0];
}

const items = $input.all();
const rows = [];

for (const item of items) {
  const r = item.json;
  const keys = Object.keys(r);
  const hasLetterCols = keys.includes('A') || keys.includes('B');

  const id = hasLetterCols ? n(r['A']) : n(r['id']);
  const employee = hasLetterCols ? s(r['B']) : s(r['ФИО']);
  const dateRaw = hasLetterCols ? r['C'] : (r['дата'] || r['date']);
  const action_date = typeof dateRaw === 'number' ? excelDate(dateRaw) : s(dateRaw);
  const office = hasLetterCols ? s(r['E']) : (s(r['Офис']) || s(r['office']));
  const department = hasLetterCols ? s(r['F']) : (s(r['Отдел']) || s(r['dept']));
  const action_type = hasLetterCols ? s(r['G']) : (s(r['Тип']) || s(r['type']));
  const group_name = hasLetterCols ? s(r['H']) : (s(r['Группа']) || s(r['group']));
  const subgroup = hasLetterCols ? s(r['I']) : (s(r['Подгруппа']) || s(r['subgroup']));
  const comment = hasLetterCols ? s(r['J']) : (s(r['Комментарий']) || s(r['comment']));
  const price = hasLetterCols ? n(r['K']) : n(r['price']);
  const service_id = hasLetterCols ? n(r['X']) : (n(r['id сервис']) || n(r['service_id']));
  const vendor = hasLetterCols ? s(r['AK']) : (s(r['Вендор']) || s(r['vendor']));

  if (!id || !service_id) continue;
  const week = getMonday(action_date);
  rows.push({ id, employee, action_date, office, department, action_type, group_name, subgroup, comment, price, service_id, vendor, week });
}

// Group rows by ISO week (Monday)
const weekMap = {};
for (const row of rows) {
  const week = row.week;
  if (!week) continue;
  if (!weekMap[week]) weekMap[week] = [];
  weekMap[week].push(row);
}

// Fallback: rows without valid date get assigned to the first available week
const undated = rows.filter(r => !r.week);
if (undated.length > 0) {
  const firstWeek = Object.keys(weekMap).sort()[0] || getMonday(new Date().toISOString().split('T')[0]);
  if (!weekMap[firstWeek]) weekMap[firstWeek] = [];
  weekMap[firstWeek].push(...undated.map(r => ({ ...r, week: firstWeek })));
}

const weekKeys = Object.keys(weekMap).sort();

// Build multi-row INSERT for uploads table (one record per week)
const uploadVals = weekKeys.map(w => `('${w}', 'report_${w}.xlsx', ${weekMap[w].length})`).join(',\n');
const insertUploadSql = `INSERT INTO uploads(report_week, filename, row_count) VALUES\n${uploadVals}\nON CONFLICT(report_week) DO UPDATE SET filename=EXCLUDED.filename, row_count=EXCLUDED.row_count\nRETURNING id, report_week::text`;

return [{ json: { rows, weekMap, weekKeys, insertUploadSql, total_row_count: rows.length } }];

// Collect all upload rows (one per week) and build uploadMap: week → report_id
const uploadRows = $input.all();
const weekMap = $('Process Rows').first().json.weekMap;

const uploadMap = {};
for (const r of uploadRows) {
  uploadMap[r.json.report_week] = r.json.id;
}
const reportIds = uploadRows.map(r => r.json.id).filter(Boolean);

function q(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function num(v) { return (v === null || v === undefined) ? 'NULL' : Number(v); }

// Map each row to its correct report_id based on its week
const allRows = [];
for (const week of Object.keys(weekMap)) {
  const reportId = uploadMap[week];
  if (!reportId) continue;
  for (const r of weekMap[week]) {
    allRows.push({ ...r, report_id: reportId });
  }
}

if (allRows.length === 0) {
  return [{ json: { sql: 'SELECT 1', reportIds, uploadMap } }];
}

const vals = allRows.map(r =>
  `(${num(r.id)},${num(r.report_id)},${q(r.employee)},${r.action_date ? q(r.action_date) + '::date' : 'NULL'},${q(r.office)},${q(r.department)},${q(r.action_type)},${q(r.group_name)},${q(r.subgroup)},${q(r.comment)},${num(r.price)},${num(r.service_id)},${q(r.vendor)})`
).join(',');

const sql = 'INSERT INTO actions(id,report_id,employee,action_date,office,department,action_type,group_name,subgroup,comment,price,service_id,vendor) VALUES ' + vals + ' ON CONFLICT(id,report_id) DO UPDATE SET employee=EXCLUDED.employee,action_type=EXCLUDED.action_type,group_name=EXCLUDED.group_name,price=EXCLUDED.price,service_id=EXCLUDED.service_id,vendor=EXCLUDED.vendor';

return [{ json: { sql, reportIds, uploadMap } }];

const reportIds = $('Build Actions SQL').first().json.reportIds || [];
const weekKeys = $('Process Rows').first().json.weekKeys || [];
const rowCount = $('Process Rows').first().json.total_row_count || 0;
return [{ json: {
  success: true,
  report_ids: reportIds,
  row_count: rowCount,
  weeks_count: weekKeys.length,
  weeks: weekKeys,
  message: `Imported ${weekKeys.length} week(s), ${rowCount} rows`
} }];

const rows = $input.all();
const reportIds = $('Build Actions SQL').first().json.reportIds || [];
const weekKeys = $('Process Rows').first().json.weekKeys || [];

const baselines = rows.filter(r => r.json.dtype === 'baseline');
const services  = rows.filter(r => r.json.dtype === 'service');
const anomalies = rows.filter(r => r.json.dtype === 'anomaly');

const periodStr = weekKeys.length > 1
  ? weekKeys[0] + ' — ' + weekKeys[weekKeys.length - 1] + ' (' + weekKeys.length + ' нед.)'
  : (weekKeys[0] || 'период');

let prompt = `Ты аналитик затрат сервисного центра по диагностике и ремонту техники.

ПЕРИОД АНАЛИЗА: ${periodStr}

КОНТЕКСТ БИЗНЕСА:
Сервисный центр принимает технику на диагностику и ремонт. Стандартный случай — это диагностика + тестирование устройства (базовый набор действий). Реальный перерасход возникает когда:
1. К диагностике добавляются лишние платные действия без явной технической необходимости
2. Одна и та же операция дублируется (например, 2 диагностики подряд)
3. Стоимость работ у вендора системно выше, чем у других за идентичный набор действий
4. Дорогостоящие запчасти/услуги применяются к простым случаям

ВАЖНО: Если набор действий включает реальный ремонт (замена экрана, замена батареи, пайка, замена разъёма и т.п.) — высокая стоимость ОПРАВДАНА, это не перерасход. Не путай сложный ремонт с завышенными ценами на простые операции.

`;

if (baselines.length > 0) {
  prompt += `ЭТАЛОННЫЕ СЛУЧАИ (zone=normal, для сравнения):\n`;
  for (const b of baselines) {
    const r = b.json;
    prompt += `• ${r.category}: цена ${r.total_price} руб. | действия: ${r.detail || '—'}\n`;
  }
  prompt += '\n';
}

if (services.length > 0) {
  prompt += `ОБРАЩЕНИЯ С ОТКЛОНЕНИЯМИ ОТ НОРМЫ (${services.length} шт.):\n`;
  for (const s of services.slice(0, 30)) {
    const r = s.json;
    const extrasNote = r.extra_actions ? ` | ЛИШНИЕ ДЕЙСТВИЯ СВЕРХ БАЗЫ: ${r.extra_actions}` : '';
    prompt += `• [${r.zone}] ${r.category} | ${r.total_price} руб. (база ${r.base_cost}, отклонение +${r.overrun_pct}%) | все действия: ${r.detail || '—'}${extrasNote}\n`;
  }
  prompt += '\n';
}

if (anomalies.length > 0) {
  prompt += `СИСТЕМНЫЕ АНОМАЛИИ (${anomalies.length} шт.):\n`;
  for (const a of anomalies.slice(0, 15)) {
    const r = a.json;
    prompt += `• [${r.zone}] ${r.category}: ${r.detail || ''}\n`;
  }
  prompt += '\n';
}

if (services.length === 0 && anomalies.length === 0) {
  prompt += 'Статистических отклонений не обнаружено.\n\n';
}

prompt += `ЗАДАЧА — НАЙДИ РЕАЛЬНЫЕ ОТКЛОНЕНИЯ:
1. Сравни каждое отклоняющееся обращение с эталоном для той же категории вендора
2. Определи: это реальный перерасход (лишние/дублирующие действия, завышенная цена за стандартную работу) или оправданно (полноценный ремонт)?
3. Найди паттерны: системные завышения у конкретных вендоров, подозрительные комбинации действий, дублирование диагностики
4. Если формульное отклонение есть, но набор действий оправдывает цену — укажи что это ложное срабатывание
5. Дай конкретные рекомендации: что именно проверить и у кого

Ответь строго в JSON без пояснений:
{"summary":"краткое резюме 2-3 предложения о реальной ситуации с перерасходами","risk_level":"low|medium|high","patterns":[{"title":"название паттерна","description":"детальное описание с цифрами","affected":"кто затронут: вендор / группа","recommendation":"что конкретно сделать"}],"top_risks":[{"name":"название риска","reason":"почему это риск, со ссылкой на конкретные случаи","priority":"high|medium|low"}]}`;

return [{ json: { prompt, reportIds, weekKeys, services_count: services.length, anomalies_count: anomalies.length } }];

const item = $input.first();
const reportIds = $('Build Actions SQL').first().json.reportIds || [];

const rawContent = item.json.content || item.json.text || item.json.output || '{}';
let analysis;
try {
  analysis = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch(e) {
  analysis = { summary: String(rawContent).slice(0, 500), risk_level: 'unknown', patterns: [], top_risks: [] };
}

if (!reportIds.length) return [{ json: { sql: 'SELECT 1', analysis } }];

const idsArr = 'ARRAY[' + reportIds.join(',') + ']';
const safeJson = JSON.stringify(analysis).replace(/'/g, "''");
const changePct = analysis.risk_level === 'high' ? 100 : analysis.risk_level === 'medium' ? 50 : 0;

const sql = `WITH del AS (DELETE FROM weekly_insights WHERE report_id = ANY(${idsArr}) AND insight_type = 'ai_analysis')
INSERT INTO weekly_insights(report_id, insight_type, message, change_pct, direction)
SELECT u.id, 'ai_analysis', '${safeJson}', ${changePct}, 'up'
FROM uploads u
WHERE u.id = ANY(${idsArr})
ORDER BY u.report_week DESC LIMIT 1`;

return [{ json: { sql, analysis } }];
